import 'package:cloud_firestore/cloud_firestore.dart';
class MajorModel { const MajorModel({required this.id,required this.name,required this.categoryId,required this.description,required this.requiredSkillIds,required this.interests,required this.careers,this.isActive=true}); final String id,name,categoryId,description; final List<String> requiredSkillIds,interests,careers; final bool isActive;
factory MajorModel.fromMap(String id,Map<String,dynamic> map)=>MajorModel(id:id,name:map['name'] as String? ?? '',categoryId:map['categoryId'] as String? ?? '',description:map['description'] as String? ?? '',requiredSkillIds:List<String>.from(map['requiredSkillIds']??const []),interests:List<String>.from(map['interests']??const []),careers:List<String>.from(map['careers']??const []),isActive:map['isActive'] as bool? ?? true);
Map<String,dynamic> toMap()=>{'name':name,'categoryId':categoryId,'description':description,'requiredSkillIds':requiredSkillIds,'interests':interests,'careers':careers,'isActive':isActive,'updatedAt':FieldValue.serverTimestamp()}; MajorModel copyWith({String? name,String? description,bool? isActive})=>MajorModel(id:id,name:name??this.name,categoryId:categoryId,description:description??this.description,requiredSkillIds:requiredSkillIds,interests:interests,careers:careers,isActive:isActive??this.isActive); }
